/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['scanpy','scanpy-cli','anndata']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=50'
    print('repo', repo)
    try:
        with urllib.request.urlopen(url, timeout=20) as r: data=json.load(r)
        for t in data.get('tags', [])[-8:]: print(' ',t.get('name'))
    except Exception as e: print('ERR',e)
PY"

